sys_script_include.script:
var AllocatorUtils = Class.create();
AllocatorUtils.prototype = {
    initialize: function() {},

    getAvailableBranches: function(current) {
        var available = [];

        var branchGR = new GlideRecord('x_1836478_cloud_0_branch');
        branchGR.addQuery('maximum_capacity', '>', 0);
        branchGR.query();

        while (branchGR.next()) {
            available.push(branchGR.getUniqueValue());
        }

        return 'sys_idIN' + available.join(',');
    },

    canUserAllocate: function() {
        var userSysId = gs.getUserID();

        var allocationGR = new GlideRecord('x_1836478_cloud_0_allocation');
        allocationGR.addQuery('sys_created_by', userSysId);
        allocationGR.addQuery('state', 3); 
        allocationGR.query();

        if (allocationGR.hasNext()) {
            return false;
        }

        return true;
    },


    type: 'AllocatorUtils'
};
